+    scheme: Scheme,
+}
+
+impl Default for RenderTree {
+    fn default() -> Self {
+        let (defaults, dark_defaults) = concrete_default_tables();
+        Self {
+            nodes: HashMap::new(),
+            overrides: BTreeMap::new(),
+            dark_overrides: BTreeMap::new(),
+            defaults,
+            dark_defaults,
+            scheme: Scheme::Light,
