//! Build script for the Qt Quick spike: locate a Qt6 install via `qmake -query`,
//! compile the C++ TU with `cc`, and hand the linker the Qt frameworks/dylibs.
//!
//! Qt location overrides: `QMAKE` env var (else the Homebrew default
//! `/opt/homebrew/opt/qt/bin/qmake`, else `qmake` on PATH).

use std::env;
use std::path::PathBuf;
use std::process::Command;

fn qmake_bin() -> PathBuf {
    if let Ok(q) = env::var("QMAKE") {
        return PathBuf::from(q);
    }
    for candidate in [
        "/opt/homebrew/opt/qt/bin/qmake",
        "/usr/local/opt/qt/bin/qmake",
    ] {
        if PathBuf::from(candidate).exists() {
            return PathBuf::from(candidate);
        }
    }
    // Fall back to PATH (qtpaths/qmake must be reachable).
    if Command::new("qmake").arg("-query").arg("QT_VERSION").output().is_ok() {
        return PathBuf::from("qmake");
    }
    panic!(
        "Qt6 not found: set QMAKE=/path/to/qmake (Homebrew: brew install qt, then QMAKE=$(brew --prefix qt)/bin/qmake)"
    );
}

fn qmake_query(qmake: &PathBuf, key: &str) -> String {
    let out = Command::new(qmake)
        .arg("-query")
        .arg(key)
        .output()
        .unwrap_or_else(|e| panic!("failed to run {qmake:?} -query {key}: {e}"));
    assert!(out.status.success(), "qmake -query {key} failed");
    String::from_utf8(out.stdout).expect("qmake output not UTF-8").trim().to_string()
}

fn main() {
    let qmake = qmake_bin();
    let headers = qmake_query(&qmake, "QT_INSTALL_HEADERS");
    let libs = qmake_query(&qmake, "QT_INSTALL_LIBS");

    // Which Qt frameworks/dylibs do we need?
    let modules = ["QtCore", "QtGui", "QtQml", "QtQuick"];

    // Homebrew Qt on macOS builds frameworks (lib/QtCore.framework); the plain
    // lib layout (Linux) is lib/libQt6Core.so. Detect which is present.
    let framework_dir = |m: &str| PathBuf::from(&libs).join(format!("{m}.framework"));

    let frameworks = modules
        .iter()
        .filter(|m| framework_dir(m).exists())
        .cloned()
        .collect::<Vec<_>>();

    let mut build = cc::Build::new();
    build.cpp(true).file("src/spike.cpp").std("c++17");
    build.include(&headers);

    if !frameworks.is_empty() {
        build.flag(&format!("-F{libs}"));
        for f in &frameworks {
            println!("cargo:rustc-link-search=native={libs}");
            println!("cargo:rustc-link-lib=framework={f}");
        }
    } else {
        // Plain shared/dynamic lib layout (Linux): -L + -lQt6* + rpath.
        println!("cargo:rustc-link-search=native={libs}");
        for m in &modules {
            println!("cargo:rustc-link-lib=dylib={}", m.replace("Qt", "Qt6"));
        }
        println!("cargo:rustc-link-arg=-Wl,-rpath,{libs}");
    }

    build.compile("qt_spike");

    // Tell the runtime which plugin/backend to use is the test's job (env vars).
    println!("cargo:rerun-if-env-changed=QMAKE");
    println!("cargo:rerun-if-changed=src/spike.cpp");
}

// M0 spike: prove the Rust-core + C++ Qt Quick FFI boundary.
//
// - Rust calls `spike_init` -> C++ builds a QQuickWindow + an imperative QML
//   scene (Row { Text; Button }) via QQmlComponent.
// - Rust calls `spike_press` -> C++ emits the Button's `clicked` signal ->
//   connected C++ handler -> C callback into Rust (no payload, like the real
//   renderer's wake callback).
// - Rust calls `spike_set_prop` -> C++ sets/reads back a QML property.
// - Rust calls `spike_shutdown` -> C++ tears everything down.
//
// This mirrors the real renderer's contract: everything runs on the Qt main
// thread; the Qt layer owns the widgets and only wakes the Rust host, which
// owns the decode + transport. Offscreen (`QT_QPA_PLATFORM=offscreen`,
// `QT_QUICK_BACKEND=software`) keeps it headless for CI.

#include <QGuiApplication>
#include <QQuickWindow>
#include <QQuickItem>
#include <QQmlEngine>
#include <QQmlComponent>
#include <QUrl>
#include <QString>
#include <QStringList>
#include <QDebug>

extern "C" {
// Callback into Rust: the Qt layer reports an event; Rust decides what to do.
typedef void (*SpikeCallback)(int id, void *user);
}

namespace {

struct State {
    QGuiApplication *app = nullptr;
    QQmlEngine *engine = nullptr;
    QQuickWindow *window = nullptr;
    QQuickItem *root = nullptr;   // window contentItem
    QQuickItem *row = nullptr;
    QQuickItem *text = nullptr;
    QQuickItem *button = nullptr;
    SpikeCallback cb = nullptr;
    void *user = nullptr;
};

State g;

QQuickItem *createComponent(QQmlEngine *engine, QQuickItem *parent, const char *qml) {
    QQmlComponent comp(engine);
    comp.setData(QString::fromUtf8(qml), QUrl());
    if (comp.isError()) {
        qWarning() << "component error:" << comp.errorString();
        return nullptr;
    }
    QObject *obj = comp.create();
    if (!obj) {
        qWarning() << "create failed:" << comp.errorString();
        return nullptr;
    }
    QQuickItem *item = qobject_cast<QQuickItem *>(obj);
    if (item && parent) {
        item->setParentItem(parent);
    }
    return item;
}

void onButtonClicked() {
    if (g.cb) {
        g.cb(0, g.user); // id 0 = button clicked
    }
}

} // namespace

extern "C" {

// Build the scene. Returns 0 on success, -1 otherwise.
int spike_init(SpikeCallback cb, void *user) {
    // QGuiApplication must be constructed exactly once and before any QGui type.
    static int argc = 1;
    static char arg0[] = "spike";
    static char *argv[] = {arg0, nullptr};
    g.app = new QGuiApplication(argc, argv);

    g.cb = cb;
    g.user = user;

    g.engine = new QQmlEngine(g.app);
    g.window = new QQuickWindow();
    g.window->resize(400, 300);
    g.root = g.window->contentItem();

    g.row = createComponent(
        g.engine, g.root,
        "import QtQuick 2.15\n"
        "Row { spacing: 8; objectName: \"row\"; }");
    if (!g.row) return -1;

    g.text = createComponent(
        g.engine, g.row,
        "import QtQuick 2.15\n"
        "Text { text: \"hello\"; objectName: \"hello\"; }");
    if (!g.text) return -1;

    g.button = createComponent(
        g.engine, g.row,
        "import QtQuick 2.15\n"
        "import QtQuick.Controls 2.15\n"
        "Button { text: \"Press\"; objectName: \"press\"; }");
    if (!g.button) return -1;

    // Wire the QML Button's `clicked` signal to the Rust callback.
    QObject::connect(g.button, SIGNAL(clicked()), []() { onButtonClicked(); });

    g.window->show(); // offscreen platform renders headlessly
    return 0;
}

// Emit the button's clicked signal (offscreen stand-in for a real press).
void spike_press() {
    QMetaObject::invokeMethod(g.button, "clicked");
}

// Set a property and return the value read back (proves Rust -> QML props).
int spike_set_prop(const char *name, const char *value) {
    g.button->setProperty(name, QString::fromUtf8(value));
    QVariant read = g.button->property(name);
    return read.isValid() && read.toString() == QString::fromUtf8(value) ? 0 : -1;
}

// The row's child count + the text's string, so Rust can assert the tree shape.
int spike_child_count() {
    if (!g.row) return -1;
    const auto children = g.row->childItems();
    return static_cast<int>(children.size());
}

int spike_text_matches(const char *expected) {
    if (!g.text) return -1;
    QVariant v = g.text->property("text");
    return v.isValid() && v.toString() == QString::fromUtf8(expected) ? 0 : -1;
}

void spike_shutdown() {
    delete g.window;
    g.window = nullptr;
    delete g.engine;
    g.engine = nullptr;
    delete g.app;
    g.app = nullptr;
}

} // extern "C"

//! M0 spike: prove the Rust-core + C++ Qt Quick FFI boundary.
//!
//! Rust drives a C++-built Qt Quick scene through `extern "C"` calls and
//! receives a wake callback when the Qt layer reports an event — the same
//! contract the real `pathland-render-qt` will use (Rust owns decode +
//! transport + wire encoding; C++ owns widgets + signals).
//!
//! Run headless:
//!   QT_QPA_PLATFORM=offscreen QT_QUICK_BACKEND=software cargo test

use std::os::raw::c_int;
use std::sync::atomic::{AtomicUsize, Ordering};

/// The callback the C++ layer invokes when a Qt event fires (no payload — the
/// real renderer only *wakes* the host; the host drains the ring itself).
pub extern "C" fn on_spike_event(_id: c_int, _user: *mut std::ffi::c_void) {
    EVENTS.fetch_add(1, Ordering::SeqCst);
}

static EVENTS: AtomicUsize = AtomicUsize::new(0);

extern "C" {
    fn spike_init(cb: extern "C" fn(c_int, *mut std::ffi::c_void), user: *mut std::ffi::c_void)
        -> c_int;
    fn spike_press();
    fn spike_set_prop(name: *const u8, value: *const u8) -> c_int;
    fn spike_child_count() -> c_int;
    fn spike_text_matches(expected: *const u8) -> c_int;
    fn spike_shutdown();
}

#[test]
fn qt_quick_round_trip_offscreen() {
    // Offscreen platform must be chosen before QGuiApplication is constructed.
    std::env::set_var("QT_QPA_PLATFORM", "offscreen");
    std::env::set_var("QT_QUICK_BACKEND", "software");

    EVENTS.store(0, Ordering::SeqCst);

    let cstr = |s: &str| -> Vec<u8> {
        let mut v = s.as_bytes().to_vec();
        v.push(0);
        v
    };

    unsafe {
        // 1. Rust -> C++: build the scene.
        assert_eq!(spike_init(on_spike_event, std::ptr::null_mut()), 0);

        // 2. Tree shape: Row has exactly two children (Text + Button).
        assert_eq!(spike_child_count(), 2);

        // 3. Rust -> QML property set, read back through C++.
        let name = cstr("text");
        let value = cstr("Changed");
        assert_eq!(spike_set_prop(name.as_ptr(), value.as_ptr()), 0);
        assert_eq!(spike_text_matches(b"hello\0".as_ptr()), 0);

        // 4. Qt signal -> C++ -> C callback -> Rust: pressed increments a
        //    Rust atomic (synchronous direct connection, no event loop).
        assert_eq!(EVENTS.load(Ordering::SeqCst), 0);
        spike_press();
        assert_eq!(EVENTS.load(Ordering::SeqCst), 1);

        // 5. Tear down.
        spike_shutdown();
    }
}

