//! Build script for `pathland-render-qt`: locate a Qt6 install via
//! `qmake -query`, run moc on the QML-facing bridge, compile the C++ widget
//! layer with `cc`, and hand the linker the Qt frameworks/dylibs.
//!
//! Qt location overrides: `QMAKE` env var (else Homebrew `/opt/homebrew/opt/qtbase/bin/qmake`,
//! else `qmake6`/`qmake` on PATH). Linux (CI) ships qmake at `/usr/bin/qmake6` and
//! moc at `/usr/lib/qt6/libexec/moc`.

use std::env;
use std::path::PathBuf;
use std::process::Command;

fn qmake_bin() -> PathBuf {
    if let Ok(q) = env::var("QMAKE") {
        return PathBuf::from(q);
    }
    for candidate in [
        "/opt/homebrew/opt/qtbase/bin/qmake",
        "/opt/homebrew/opt/qt/bin/qmake",
        "/usr/local/opt/qt/bin/qmake",
    ] {
        if PathBuf::from(candidate).exists() {
            return PathBuf::from(candidate);
        }
    }
    // Fall back to qmake6/qmake on PATH (Linux CI, other installs).
    for name in ["qmake6", "qmake"] {
        if Command::new(name).arg("-query").arg("QT_VERSION").output().is_ok() {
            return PathBuf::from(name);
        }
    }
    panic!(
        "Qt6 not found: set QMAKE=/path/to/qmake (Homebrew: brew install qtbase qtdeclarative, then QMAKE=$(brew --prefix qtbase)/bin/qmake)"
    );
}

fn qmake_query(qmake: &PathBuf, key: &str) -> String {
    let out = Command::new(qmake)
        .arg("-query")
        .arg(key)
        .output()
        .unwrap_or_else(|e| panic!("failed to run {qmake:?} -query {key}: {e}"));
    assert!(out.status.success(), "qmake -query {key} failed");
    String::from_utf8(out.stdout)
        .expect("qmake output not UTF-8")
        .trim()
        .to_string()
}

fn moc_name(header: &str) -> String {
    let base = header
        .rsplit('/')
        .next()
        .unwrap_or(header)
        .strip_suffix(".h")
        .unwrap_or(header);
    format!("moc_{base}")
}

fn find_moc(qmake: &PathBuf) -> PathBuf {
    let qt_bin = qmake.parent().expect("qmake must live in a bin dir");
    let prefix = qt_bin.parent().expect("qmake bin has a prefix");
    let candidates = [
        qt_bin.join("moc"),
        qt_bin.join("moc6"),
        prefix.join("share/qt/libexec/moc"),
        PathBuf::from("/opt/homebrew/share/qt/libexec/moc"),
        PathBuf::from("/usr/local/share/qt/libexec/moc"),
        PathBuf::from("/usr/lib/qt6/libexec/moc"),
        PathBuf::from("/usr/lib/x86_64-linux-gnu/qt6/libexec/moc"),
    ];
    for c in &candidates {
        if c.exists() {
            return c.clone();
        }
    }
    for name in ["moc", "moc6"] {
        if Command::new(name).arg("-V").output().is_ok() {
            return PathBuf::from(name);
        }
    }
    panic!(
        "moc not found (looked next to qmake and in standard Qt libexec paths); set QMAKE to a qtbase qmake"
    );
}

fn main() {
    let qmake = qmake_bin();
    let headers = qmake_query(&qmake, "QT_INSTALL_HEADERS");
    let libs = qmake_query(&qmake, "QT_INSTALL_LIBS");

    // Which Qt frameworks/dylibs do we need? QML controls call into a QObject
    // bridge via context-property invokables, so only Core/Qml/Quick + the
    // moc-generated meta-object code are required (no Controls C++ libs).
    let modules = ["QtCore", "QtGui", "QtQml", "QtQuick"];

    let framework_dir = |m: &str| PathBuf::from(&libs).join(format!("{m}.framework"));
    let frameworks = modules
        .iter()
        .filter(|m| framework_dir(m).exists())
        .cloned()
        .collect::<Vec<_>>();

    // Qt frameworks keep their public headers under a versioned subdir of
    // `<M>.framework/Headers/` (Homebrew layout); add those dirs so
    // `#include <QtQml/QQmlEngine>` resolves.
    let framework_header_dirs = |framework: &str| -> Vec<String> {
        let base = PathBuf::from(&libs).join(format!("{framework}.framework/Headers"));
        let mut dirs = Vec::new();
        if let Ok(rd) = std::fs::read_dir(&base) {
            for e in rd.flatten() {
                if e.file_type().map(|t| t.is_dir()).unwrap_or(false) {
                    dirs.push(e.path().to_string_lossy().into_owned());
                }
            }
        }
        dirs
    };

    let mut build = cc::Build::new();
    build
        .cpp(true)
        .files([
            "src/qt/qt_layer.cpp",
            "src/qt/bridge.cpp",
        ])
        .std("c++17");
    build.include(&headers);
    build.include("src/qt"); // so `#include "bridge.h"` / "pathland_qt.h" resolve
    for f in &frameworks {
        for d in framework_header_dirs(f) {
            build.include(&d);
        }
    }

    // moc the QML-facing bridge so QML can invoke its slot.
    let out_dir = env::var("OUT_DIR").expect("OUT_DIR set by cargo");
    let moc = find_moc(&qmake);
    for h in ["src/qt/bridge.h"] {
        let status = Command::new(&moc)
            .arg(h)
            .arg("-I")
            .arg("src/qt")
            .arg("-o")
            .arg(format!("{out_dir}/{}.cpp", moc_name(h)))
            .status()
            .unwrap_or_else(|e| panic!("failed to run moc on {h}: {e}"));
        assert!(status.success(), "moc on {h} failed");
        build.file(format!("{out_dir}/{}.cpp", moc_name(h)));
    }

    if !frameworks.is_empty() {
        build.flag(&format!("-F{libs}"));
        for f in &frameworks {
            println!("cargo:rustc-link-search=native={libs}");
            println!("cargo:rustc-link-lib=framework={f}");
        }
        // Frameworks are found via -F, not -L.
        println!("cargo:rustc-link-arg=-F{libs}");
    } else {
        // Plain shared lib layout (Linux): -L + -lQt6* + rpath.
        println!("cargo:rustc-link-search=native={libs}");
        for m in &modules {
            println!("cargo:rustc-link-lib=dylib={}", m.replace("Qt", "Qt6"));
        }
        println!("cargo:rustc-link-arg=-Wl,-rpath,{libs}");
    }

    build.compile("pathland_qt_layer");

    println!("cargo:rerun-if-env-changed=QMAKE");
    for f in [
        "src/qt/qt_layer.cpp",
        "src/qt/bridge.cpp",
        "src/qt/bridge.h",
        "src/qt/pathland_qt.h",
    ] {
        println!("cargo:rerun-if-changed={f}");
    }
}

// Shared C ABI types between the Rust decode core and the C++ Qt widget layer.
//
// A `PathlandQtCommand` is one delta: Rust produces a batch (mirroring the
// opcode engine's "only changes" discipline) and C++ applies it to the Qt Quick
// scene. This is deliberately a flat struct — the renderer's FFI boundary stays
// a batch of small commands, never a serialized tree.
#ifndef PATHLAND_QT_LAYER_H
#define PATHLAND_QT_LAYER_H

#include <stdint.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef enum PathlandQtCommandKind {
    PLQT_CREATE_NODE = 0,   /* a=id, b=componentType(u16 low)                    */
    PLQT_DELETE_NODE = 1,   /* a=id                                              */
    PLQT_INSERT_CHILD = 2,  /* a=parent, b=child, c=index (u32::MAX = append)    */
    PLQT_REMOVE_CHILD = 3,  /* a=parent, b=child                                 */
    PLQT_MOVE_CHILD = 4,    /* a=parent, b=child, c=newIndex                     */
    PLQT_SET_TEXT = 5,      /* a=id, str=text                                    */
    PLQT_SET_PROPERTY = 6,  /* a=id, b=(valueType<<16)|propertyId, c=value       */
    PLQT_SET_STRING_PROPERTY = 7, /* a=id, b=propertyId, str=value              */
    PLQT_RESET_NODE = 8,    /* a=id — reset the widget to renderer defaults      */
    PLQT_SET_SCHEME = 9,    /* a=scheme (0 light, 1 dark)                        */
} PathlandQtCommandKind;

typedef struct PathlandQtCommand {
    uint8_t kind;
    uint32_t a;
    uint32_t b;
    uint32_t c;
    uint32_t str_len;
    const char *str;
} PathlandQtCommand;

/* Wake callback into the Rust host: a Qt event fired; the host drains its own
   event ring (renderer never drains). */
typedef void (*PathlandQtWake)(void *user);
/* Qt timer tick -> Rust pump (drain pending frames), like GTK's idle pump. */
typedef void (*PathlandQtTick)(void *user);

/* Own the Qt application shell (QGuiApplication + QQuickWindow + engine +
   root item + idle tick timer). Blocks until the window closes / quit. */
int pathland_qt_layer_run(const char *title, int width, int height,
                          PathlandQtWake wake, PathlandQtTick tick, void *user);

/* Apply a batch of delta commands to the Qt Quick scene. */
void pathland_qt_layer_apply(const PathlandQtCommand *cmds, uint32_t count);

/* Reset the whole scene (META::RESET). */
void pathland_qt_layer_reset(void);

/* Quit the event loop (host-initiated shutdown). */
void pathland_qt_layer_quit(void);

#ifdef __cplusplus
}
#endif

#endif /* PATHLAND_QT_LAYER_H */

// The QML-facing bridge: QML controls call its invokables (e.g. a Button's
// `onClicked: bridge.controlEvent(7)`), and it forwards to the Rust wake
// callback. This is the C++ widget layer's only surface back to the host —
// the host owns the transport + wire encoding and only needs to know "an
// event happened". See pathland_qt.h for the command/wake types.
#ifndef PATHLAND_QT_BRIDGE_H
#define PATHLAND_QT_BRIDGE_H

#include <QtCore/QObject>
#include "pathland_qt.h"

class Bridge : public QObject {
    Q_OBJECT
public:
    explicit Bridge(QObject *parent = nullptr);
    // Assigned by the shell; invoked when any QML control reports an input.
    PathlandQtWake wake = nullptr;
    void *user = nullptr;

public slots:
    // Called from QML: `onClicked: bridge.controlEvent(nodeId)` etc.
    void controlEvent(quint32 nodeId);
    // Programmatic value/state change echoes from a control (QML -> host).
    void valueEvent(quint32 nodeId);
    void textEvent(quint32 nodeId, const QString &text);
};

#endif // PATHLAND_QT_BRIDGE_H

#include "bridge.h"

Bridge::Bridge(QObject *parent) : QObject(parent) {}

void Bridge::controlEvent(quint32 nodeId) {
    Q_UNUSED(nodeId);
    if (wake) {
        wake(user);
    }
}

void Bridge::valueEvent(quint32 nodeId) {
    Q_UNUSED(nodeId);
    if (wake) {
        wake(user);
    }
}

void Bridge::textEvent(quint32 nodeId, const QString &text) {
    Q_UNUSED(nodeId);
    Q_UNUSED(text);
    if (wake) {
        wake(user);
    }
}

// The C++ Qt Quick shell for `pathland-render-qt`.
//
// Owns the Qt application objects (QGuiApplication / QQuickWindow / QQmlEngine /
// a root Item / the QML-facing Bridge) and the idle tick timer that pumps the
// ring on the Qt main thread. The shell is split so tests can `init` the scene
// headless (offscreen) and drive `apply` without entering the event loop.
//
// M2 skeleton: `apply` is a stub that records what it received (so Rust tests
// prove the FFI batch marshalling end-to-end); the real component->QML mapping
// lands in M3.

#include "pathland_qt.h"

#include <QtGui/QGuiApplication>
#include <QtQuick/QQuickWindow>
#include <QtQuick/QQuickItem>
#include <QtQml/QQmlEngine>
#include <QtQml/QQmlComponent>
#include <QtQml/QQmlContext>
#include <QtCore/QTimer>
#include <QtCore/QUrl>
#include <QtCore/QByteArray>
#include <QtCore/QString>
#include <QtCore/QDebug>

#include "bridge.h"

namespace {

struct LayerState {
    QGuiApplication *app = nullptr;
    QQmlEngine *engine = nullptr;
    QQuickWindow *window = nullptr;
    QQuickItem *root = nullptr; // window contentItem: parent of every top-level node
    Bridge *bridge = nullptr;
    QTimer *tick_timer = nullptr;
    bool initialized = false;

    // Test hooks: record what `apply` received (kept even after M3 mapping).
    uint32_t apply_count = 0;
    uint32_t last_text_len = 0;
    char last_text[4096] = {0};
};

LayerState g;

bool init_app(int argc, char **argv) {
    g.app = new QGuiApplication(argc, argv);
    return g.app != nullptr;
}

QQuickItem *createComponent(QQmlEngine *engine, QQuickItem *parent, const char *qml) {
    QQmlComponent comp(engine);
    comp.setData(QByteArray(qml), QUrl());
    if (comp.isError()) {
        qWarning() << "component error:" << comp.errorString();
        return nullptr;
    }
    QObject *obj = comp.create();
    if (!obj) {
        qWarning() << "create failed:" << comp.errorString();
        return nullptr;
    }
    QQuickItem *item = qobject_cast<QQuickItem *>(obj);
    if (item && parent) {
        item->setParentItem(parent);
    }
    return item;
}

} // namespace

extern "C" {

int pathland_qt_layer_init(PathlandQtWake wake, PathlandQtTick tick, void *user) {
    if (g.initialized) {
        return 0;
    }
    static int argc = 1;
    static char arg0[] = "pathland-qt";
    static char *argv[] = {arg0, nullptr};
    if (!init_app(argc, argv)) {
        return -1;
    }

    g.bridge = new Bridge(g.app);
    g.bridge->wake = wake;
    g.bridge->user = user;

    g.engine = new QQmlEngine(g.app);
    g.engine->rootContext()->setContextProperty("bridge", g.bridge);

    g.window = new QQuickWindow();
    g.window->setTitle(QString::fromUtf8("Pathland"));
    g.window->resize(420, 220);
    g.root = g.window->contentItem();

    // Idle tick: pump the ring on the Qt main thread between frames, like the
    // GTK renderer's glib idle pump. A zero-millisecond repeating timer runs
    // when the event loop is free.
    g.tick_timer = new QTimer(g.app);
    g.tick_timer->setInterval(0);
    g.tick_timer->setSingleShot(false);
    QObject::connect(g.tick_timer, &QTimer::timeout, g.app, [tick, user]() {
        if (tick) {
            tick(user);
        }
    });

    g.initialized = true;
    return 0;
}

int pathland_qt_layer_run(const char *title, int width, int height,
                          PathlandQtWake wake, PathlandQtTick tick, void *user) {
    if (pathland_qt_layer_init(wake, tick, user) != 0) {
        return -1;
    }
    if (title) {
        g.window->setTitle(QString::fromUtf8(title));
    }
    if (width > 0 && height > 0) {
        g.window->resize(width, height);
    }
    g.tick_timer->start();
    g.window->show();
    const int rc = g.app->exec();
    return rc;
}

void pathland_qt_layer_apply(const PathlandQtCommand *cmds, uint32_t count) {
    if (!g.initialized || !cmds || count == 0) {
        return;
    }
    // M2: stub — record what crossed the boundary (mapping lands in M3).
    for (uint32_t i = 0; i < count; ++i) {
        const PathlandQtCommand &c = cmds[i];
        if (c.kind == PLQT_SET_TEXT && c.str && c.str_len > 0) {
            const uint32_t n = c.str_len < sizeof(g.last_text) - 1 ? c.str_len
                                                                   : sizeof(g.last_text) - 1;
            memcpy(g.last_text, c.str, n);
            g.last_text[n] = '\0';
            g.last_text_len = n;
        }
        // Other kinds are ignored until the real mapping lands (M3).
    }
    g.apply_count += count;
}

void pathland_qt_layer_reset(void) {
    g.apply_count = 0;
    g.last_text_len = 0;
    g.last_text[0] = '\0';
}

void pathland_qt_layer_quit(void) {
    if (g.app) {
        g.app->quit();
    }
}

// Test hooks ---------------------------------------------------------------

uint32_t pathland_qt_layer_apply_count(void) {
    return g.apply_count;
}

uint32_t pathland_qt_layer_last_text(char *out, uint32_t cap) {
    if (!out || cap == 0) {
        return g.last_text_len;
    }
    const uint32_t n = g.last_text_len < cap ? g.last_text_len : cap - 1;
    memcpy(out, g.last_text, n);
    out[n] = '\0';
    return n;
}

void pathland_qt_layer_shutdown(void) {
    delete g.window;
    g.window = nullptr;
    delete g.engine;
    g.engine = nullptr;
    delete g.app;
    g.app = nullptr;
    g.bridge = nullptr;
    g.tick_timer = nullptr;
    g.root = nullptr;
    g.initialized = false;
}

} // extern "C"

