mod tests {
    use super::*;
    use pathland_core::{init_memory, Frame, Guest, Host, MemoryLayout};
    use pathland_engine::Engine;
    use pathland_view::{assign_ids, text, vstack, View, ViewExt};

    /// Emit a view into fresh ring memory and copy the resulting frame's slots
    /// + arena into owned buffers, so a [`Frame`] view can outlive the emit
    /// scope. Returns `(slots, arena)`; the frame spans `0..slots.len()`.
    fn owned_frame(root: &dyn View) -> (Vec<u8>, Vec<u8>) {
        let layout = MemoryLayout::default();
        let mut mem = vec![0u8; layout.total_bytes()];
        init_memory(&mut mem, &layout);
        let mut engine = Engine::new();
        {
            let mut guest = Guest::new(&mut mem, &layout);
            guest.begin_frame();
            engine.emit(root, &mut guest).unwrap();
            guest.end_frame();
        }
        let mut host = Host::new(&mut mem, &layout);
        let frames = host.frames();
        assert_eq!(frames.len(), 1, "one frame per emit");
        let f = &frames[0];
        let mut slots = Vec::with_capacity(f.len() * 16);
        for op in f.opcodes() {
            slots.extend_from_slice(&op.to_bytes());
        }
        let arena = f.arena().to_vec();
        (slots, arena)
    }

    fn apply_first(r: &mut QtRenderer, root: &dyn View) {
        let (slots, arena) = owned_frame(root);
        let frame = Frame::from_parts(&slots, &arena, 0, slots.len());
